static void require(bool ok,const char *message) { if(!ok)throw std::runtime_error(message); }
static void events() { QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QApplication::processEvents(); }
static QByteArray read(const QString &path) { QFile f(path);require(f.open(QIODevice::ReadOnly),"Plot field artifact absent");return f.readAll(); }
static void write(const QString &path,const QByteArray &bytes) { QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size(),"Plot field artifact write failed"); }
static void reveal(QWidget *widget) {
 require(widget,"Plot field widget absent");
 for(auto *p=widget->parentWidget();p;p=p->parentWidget())if(auto *scroll=qobject_cast<QScrollArea *>(p))scroll->ensureWidgetVisible(widget,8,8);
 events();require(widget->isVisible()&&widget->isEnabled(),"Plot field widget unavailable");acceptanceView(*widget);
}
static void paste(QLineEdit *field,const QString &value) {
 reveal(field);QTest::mouseClick(field,Qt::LeftButton);QTest::keyClick(field,Qt::Key_A,Qt::ControlModifier);
 QApplication::clipboard()->setText(value);QTest::keyClick(field,Qt::Key_V,Qt::ControlModifier);events();require(field->text()==value,"Plot field paste altered input");
}
static PlotCommand *probe() {
 QSet<GmatCommand *> seen;
 for(auto *c=Moderator::Instance()->GetFirstCommand();c&&!seen.contains(c);c=c->GmatCommand::GetNext()){
  seen.insert(c);if(missionCommandLabel(QString::fromStdString(c->GetGeneratingString(Gmat::NO_COMMENTS))).name=="Probe")return dynamic_cast<PlotCommand *>(c);
 }
 return nullptr;
}
static QStringList references() {
 auto *c=probe();require(c,"Plot field native command absent");QStringList names;
 for(const auto &name:c->GetRefObjectNameArray(Gmat::SUBSCRIBER))names.append(QString::fromStdString(name));return names;
}
static QJsonObject model(const PlotModel &m) {
 QJsonArray curves;
 for(auto it=m.curves.cbegin();it!=m.curves.cend();++it){QJsonArray points;for(const auto &p:it->points)points.append(QJsonArray{p.x,p.y,p.z,p.epoch,double(p.frame),p.connect,p.highlighted});curves.append(QJsonObject{{"name",it->name},{"points",points}});}
 return QJsonObject{{"kind",int(m.kind)},{"pen_down",m.penDown},{"active",m.active},{"curves",curves}};
}
class InputTrace:public QObject {
public:
 QPointer<QWidget> viewport;int presses=0,moves=0,drops=0;QJsonArray records;
 bool eventFilter(QObject *object,QEvent *event)override{const auto t=event->type();if((t==QEvent::MouseButtonPress||t==QEvent::MouseMove||t==QEvent::MouseButtonRelease)&&event->spontaneous()){if(t==QEvent::MouseButtonPress)++presses;if(t==QEvent::MouseMove)++moves;records.append(QJsonObject{{"type",int(t)},{"native",true},{"receiver",object->objectName()}});}if(object==viewport&&(t==QEvent::DragEnter||t==QEvent::DragMove||t==QEvent::DragLeave||t==QEvent::Drop)){if(t==QEvent::Drop)++drops;records.append(QJsonObject{{"type",int(t)},{"viewport",true},{"native",event->spontaneous()}});}return false;}
};
class XInput {
 QLibrary x{"X11",6},xt{"Xtst",6};void *display=nullptr;
 using Open=void *(*)(const char *);using Close=int(*)(void *);using Flush=int(*)(void *);using Motion=int(*)(void *,int,int,int,unsigned long);using Button=int(*)(void *,unsigned int,int,unsigned long);using Key=int(*)(void *,unsigned int,int,unsigned long);using Code=unsigned char(*)(void *,unsigned long);using Query=int(*)(void *,int *,int *,int *,int *);
 Close close=nullptr;Flush flush=nullptr;Motion motion=nullptr;Button click=nullptr;Key key=nullptr;Code code=nullptr;
public:
 QJsonObject metadata;
 explicit XInput(const QString &evidence){require(QGuiApplication::platformName()=="xcb"&&qEnvironmentVariable("GMAT_QT_NATIVE_TEST_LAUNCH")=="1"&&!evidence.isEmpty(),"Native picker drag requires owned native acceptance launcher");const auto receipt=QJsonDocument::fromJson(read(QDir(evidence).filePath("../results.json"))).object();const bool visible=qEnvironmentVariable("GMAT_QT_ACCEPTANCE_MODE")=="visible";if(visible){const auto authority=QFileInfo(QDir(evidence).filePath("../display/Xauthority")).canonicalFilePath();require(receipt["display_route"]=="nested"&&receipt["display"].toString()!=qEnvironmentVariable("DISPLAY")&&!authority.isEmpty()&&QFileInfo(qEnvironmentVariable("XAUTHORITY")).canonicalFilePath()==authority,"Native picker drag refuses host-display input");}else require(receipt["mode"]=="headless","Native picker drag requires private-Xvfb unattended receipt");require(x.load()&&xt.load(),"Native picker drag X11/XTest library absent");auto open=reinterpret_cast<Open>(x.resolve("XOpenDisplay"));close=reinterpret_cast<Close>(x.resolve("XCloseDisplay"));flush=reinterpret_cast<Flush>(x.resolve("XFlush"));motion=reinterpret_cast<Motion>(xt.resolve("XTestFakeMotionEvent"));click=reinterpret_cast<Button>(xt.resolve("XTestFakeButtonEvent"));key=reinterpret_cast<Key>(xt.resolve("XTestFakeKeyEvent"));code=reinterpret_cast<Code>(x.resolve("XKeysymToKeycode"));auto query=reinterpret_cast<Query>(xt.resolve("XTestQueryExtension"));require(open&&close&&flush&&motion&&click&&key&&code&&query,"Native picker drag XTest symbols absent");display=open(qgetenv("DISPLAY").constData());int e=0,err=0,major=0,minor=0;require(display&&query(display,&e,&err,&major,&minor),"Native picker drag display lacks XTest");metadata=QJsonObject{{"display",qEnvironmentVariable("DISPLAY")},{"visible",visible},{"route",visible?QString("owned nested Xephyr"):QString("native launcher private Xvfb")},{"xtest_major",major},{"xtest_minor",minor},{"physical_device",false}};}
 ~XInput(){if(display){click(display,1,0,0);flush(display);close(display);}}
 bool move(QPoint p,double scale){const bool ok=motion(display,-1,qRound(p.x()*scale),qRound(p.y()*scale),0);flush(display);return ok;}
 bool button(bool down){const bool ok=click(display,1,down,0);flush(display);return ok;}
 bool escape(){const auto k=code(display,0xff1b);const bool ok=k&&key(display,k,1,0)&&key(display,k,0,0);flush(display);return ok;}
};

